import os,urllib.request,json
H={"Authorization":"Bearer "+os.environ["API_TOKEN"],"Accept":"application/hal+json","Accept-Profile":"<https://w3id.org/heart-rise/hal-schema-forms>","Prefer":"forms=link, schema=link","Content-Type":"application/json"}
body=json.dumps({"firstName":"Frodo","lastName":"Baggins","position":"ring bearer, retired"}).encode()
try:
    r=urllib.request.urlopen(urllib.request.Request(os.environ["API_BASE"]+"/employees/1/actions/update",data=body,method="PUT",headers=H))
    print(r.status,r.read().decode())
